good_example:
// Trackball con quaternions - un solo eje de giro combinado por gesto, sin gimbal lock ni clamp
function girarPorArrastre(dx, dy) {
  const eje = new THREE.Vector3(dy, dx, 0).normalize();
  const angulo = Math.sqrt(dx * dx + dy * dy) * 0.006;
  const delta = new THREE.Quaternion().setFromAxisAngle(eje, angulo);
  objeto.quaternion.premultiply(delta);
}

